<style>
  .iso {
    position: relative;
    width: 100%;
    aspect-ratio: 131 / 238;
    /* Depth step between adjacent layers. */
    --depth: 22px;
    transform-style: preserve-3d;
    transition: transform 0.5s;
  }

  .iso:hover {
    transform: rotateX(33deg) rotateY(-45deg);
    /*transform: rotateX(33deg) rotateY(45deg) skew(-33deg) rotateZ(-33deg) scaleY(120%)*/
  }

  .iso:hover > .layer {
    /*border-color: var(--flexoki-base-850);*/
  }

  .layer {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: 1.5px dashed;
    border-color: transparent;
    transition: border-color 0.5s;
  }

  .frame {
    transform: translateZ(calc(var(--depth) * 1.5));
  }

  .mid-text {
    transform: translateZ(calc(var(--depth) * 0.5));
  }

  .dragon {
    transform: translateZ(calc(var(--depth) * -0.5));
  }

  .bottom-text {
    transform: translateZ(calc(var(--depth) * -1.5));
  }
</style>
